#!/usr/bin/env node
import { execFileSync } from 'node:child_process'
import { createRequire } from 'node:module'

const require = createRequire(import.meta.url)
const map = __PLATFORM_MAP__
const key = process.platform + '-' + process.arch
const pkg = map[key]

if (!pkg) {
  console.error('Unsupported platform: ' + key)
  process.exit(1)
}

const ext = process.platform === 'win32' ? '.exe' : ''

try {
  const bin = require.resolve(`${pkg}/bin/__CLI_BIN_NAME__${ext}`)
  execFileSync(bin, process.argv.slice(2), { stdio: 'inherit' })
} catch {
  console.error('Binary not found. Try reinstalling ' + pkg + '.')
  process.exit(1)
}

# Command Definition API

## defineCommand

Type helper for defining commands with proper type inference.

```typescript
import { defineCommand, option } from "@bunli/core";
import { z } from "zod";

export const myCommand = defineCommand({
  name: "mycommand",
  description: "My command description",
  alias: "mc", // optional: string or string[]
  options: {
    debug: option(z.boolean().default(false), { short: "d", description: "Debug output" }),
  },
  handler: async ({ flags, prompt, spinner, signal }) => {
    if (signal.aborted) return;
    if (flags.debug) prompt.log.info("Running...");
    const s = spinner("Work in progress...");
    s.succeed("Done");
  },
});
```

For nested command trees, use `defineGroup(...)`:

```typescript
import { defineGroup } from "@bunli/core";

export const adminGroup = defineGroup({
  name: "admin",
  description: "Admin commands",
  commands: [usersCommand, rolesCommand],
});
```

## option()

Creates a CLI option with StandardSchema validation.

Use `z.coerce.number()` for numeric flags because CLI args are strings.

```typescript
name: option(z.string(), { short: "n", description: "Your name" });
debug: option(z.boolean(), { short: "d", description: "Enable debug output" });
port: option(z.coerce.number(), { description: "Port number" });
mode: option(z.enum(["dev", "prod"]).default("dev"));
```

## Positional arguments

Read positionals from `handler` args:

```typescript
handler: ({ positional }) => {
  const [first, second, ...rest] = positional;
};
```

## Runnable command shape

Runnable commands can provide:

- `handler` only (non-TUI flow)
- `render` only (TUI-only flow)
- both `handler` and `render` (dual mode)

Commands can also provide command-level renderer overrides:

```typescript
{
  tui: {
    renderer: {
      bufferMode: "standard";
    }
  }
}
```

## Handler context

```typescript
handler: ({
  flags,
  positional,
  shell,
  env,
  cwd,
  prompt,
  spinner,
  colors,
  terminal,
  runtime,
  signal,
  context,
}) => {
  // flags: parsed option values
  // positional: positional arguments
  // shell: Bun.$
  // env: process.env
  // cwd: current working directory
  // prompt/spinner: @bunli/runtime/prompt APIs
  // colors: @bunli/utils colors
  // terminal: width, height, isInteractive, isCI, supportsColor, supportsMouse
  // runtime: startTime, args, command
  // signal: cooperative cancellation signal
  // context: plugin command context (if plugins are loaded)
};
```

# Type Safety Patterns

## StandardSchema integration

Bunli uses `@standard-schema/spec` for validation with full type inference.

```typescript
import { option } from "@bunli/core";
import { z } from "zod";

const opts = {
  name: option(z.string(), { description: "Your name" }),
};

// Option schemas are inferred into handler `flags` types automatically.
```

## Generated types

`@bunli/generator` parses command files and generates TypeScript types.

```typescript
// .bunli/commands.gen.ts (auto-generated)
export interface RegisteredCommands {
  hello: Command<{ name: typeof nameOption }, {}, "hello">;
}

// Type-safe execution
cli.execute("hello", { name: "World" });
```

## Module augmentation

```typescript
declare module "@bunli/core" {
  interface RegisteredCommands {
    mycmd: typeof myCommand;
  }
}
```

## Handler type inference

```typescript
type Handler<TFlags, TStore, TCommandName> = (
  args: HandlerArgs<TFlags, TStore, TCommandName>,
) => void | Promise<void>;

interface HandlerArgs<TFlags, TStore, TCommandName> {
  flags: TFlags;
  positional: string[];
  shell: typeof Bun.$;
  env: typeof process.env;
  cwd: string;
  prompt: import("@bunli/runtime/prompt").PromptApi;
  spinner: import("@bunli/runtime/prompt").PromptSpinnerFactory;
  colors: typeof import("@bunli/utils").colors;
  terminal: TerminalInfo;
  runtime: RuntimeInfo;
  signal: AbortSignal;
  context?: import("@bunli/core/plugin").CommandContext<Record<string, unknown>>;
}
```

# Built-in Plugins

## @bunli/plugin-ai-detect

Detects AI coding assistants from environment variables.

```typescript
import { aiAgentPlugin } from "@bunli/plugin-ai-detect";

const plugin = aiAgentPlugin();
```

Adds AI-related fields via plugin augmentation (`context.env.isAIAgent`, `context.env.aiAgents`) and can also project data into plugin store.

## @bunli/plugin-completions

Generates shell completions.

```typescript
import { completionsPlugin } from "@bunli/plugin-completions";

const plugin = completionsPlugin({
  generatedPath: ".bunli/commands.gen.ts",
  commandName: "mycli",
  executable: "mycli",
  includeAliases: true,
  includeGlobalFlags: true,
});
```

Note: package name is `@bunli/plugin-completions`, while the registered runtime plugin name is `completions`.

## @bunli/plugin-config

Loads config from multiple sources with merging.

```typescript
import { configMergerPlugin } from "@bunli/plugin-config";

const plugin = configMergerPlugin({
  sources: [
    "~/.config/{{name}}/config.json",
    ".{{name}}rc",
    ".{{name}}rc.json",
    ".config/{{name}}.json",
  ],
  mergeStrategy: "deep",
});
```

## @bunli/plugin-mcp

Converts MCP tools to CLI commands.

```typescript
import { mcpPlugin } from "@bunli/plugin-mcp";

const plugin = mcpPlugin({
  toolsProvider: async () => [
    {
      namespace: "server",
      tools: [{ name: "tool1", description: "...", inputSchema: { type: "object" } }],
    },
  ],
  createHandler:
    (namespace, toolName) =>
    async ({ flags }) => {
      return mcpClient.callTool(`${namespace}:${toolName}`, flags);
    },
  sync: { outputDir: ".bunli" }, // or sync: true
});
```

`sync` accepts:

- `true` (default output dir `.bunli`)
- `{ outputDir?: string }`

## Plugin composition

```typescript
import { composePlugins } from "@bunli/core/plugin";

const app = composePlugins(
  aiAgentPlugin(),
  configMergerPlugin({ sources: [] }),
  completionsPlugin(),
  mcpPlugin({ toolsProvider, createHandler }),
);
```

# Plugin System

## BunliPlugin interface

```typescript
interface BunliPlugin<TStore = {}> {
  name: string;
  version?: string;
  store?: TStore;

  setup?(context: PluginContext): void | Promise<void>;
  configResolved?(config: ResolvedConfig): void | Promise<void>;
  beforeCommand?(context: CommandContext<any>): void | Promise<void>;
  afterCommand?(context: CommandContext<any> & CommandResult): void | Promise<void>;
}
```

## Plugin context (setup phase)

```typescript
interface PluginContext {
  readonly config: BunliConfigInput;
  updateConfig(partial: Partial<BunliConfigInput>): void;
  registerCommand(command: CommandDefinition): void;
  use(middleware: Middleware): void;
  readonly store: Map<string, unknown>;
  readonly logger: Logger;
  readonly paths: PathInfo; // cwd, home, config
}
```

`setup` store is a shared `Map<string, unknown>` for plugin setup coordination.

## Command context (execution phase)

```typescript
interface CommandContext<TStore = {}> {
  readonly command: string;
  readonly commandDef: Command<any, TStore>;
  readonly args: string[];
  readonly flags: Record<string, unknown>;
  readonly env: EnvironmentInfo;
  readonly store: TStore;
  getStoreValue<K extends keyof TStore>(key: K): TStore[K];
  setStoreValue<K extends keyof TStore>(key: K, value: TStore[K]): void;
  hasStoreValue<K extends keyof TStore>(key: K): boolean;
}
```

Execution `store` is a typed object copied from merged plugin stores for each command run.

`EnvironmentInfo` base field is `isCI`; additional fields like `isAIAgent`/`aiAgents` come from plugins (for example `@bunli/plugin-ai-detect`).

## Creating plugins

```typescript
import { createPlugin } from "@bunli/core/plugin";

const myPlugin = createPlugin({
  name: "my-plugin",
  store: { count: 0 },
  beforeCommand(context) {
    context.store.count++;
  },
});

const myFactoryPlugin = createPlugin((options: { prefix: string }) => ({
  name: "my-factory-plugin",
  beforeCommand(context) {
    console.log(`${options.prefix}: ${context.command}`);
  },
}));
```

## Plugin configuration

```typescript
export default defineConfig({
  plugins: [
    "@bunli/plugin-ai-detect",
    myPlugin,
    [completionsPlugin, { generatedPath: ".bunli/commands.gen.ts" }],
  ],
});
```

